// --- Safety Guardrails for Thumbnail and Sandbox ---
if (typeof width === 'undefined') { var width = 1280; }
if (typeof height === 'undefined') { var height = 720; }


// --- Global Variables for Uncler M Variants ---
var uM_colors = ["#ffffff", "#000000", "#71717a", "#27272a", "#f4f4f5"];
var speedMult = 1.0;
var lineScale = 1.0;
var dynamicShift = 0;
var scalePulse = 1.0;
var rotAngle = 0;
var gridOffset = 0;
var uM_rot = 0;

// === Inspired by 'gradation' by 'reona396' ===
// Created as variant #2 by Uncler M
// Infused with creative algorithmic modifications.

// === Tab: mySketch ===
var shapes = [];
var shapesNum = 5000;
var sMax;

function setup() {
  createCanvas(windowWidth, windowHeight);

  sMax = max(width, height) * 0.3;

  for (let i = 0; i < shapesNum; i++) {
    shapes.push(new Shape(i));
  }

  background("#E7ECF2");
}

function draw() {
  // === Variant 2: Organic Lissajous Morph ===
  scalePulse = 1.0 + 0.25 * sin(frameCount * 0.03);
  rotAngle = frameCount * 0.015;
  push();
  translate(width/2, height/2);
  rotate(rotAngle);
  scale(scalePulse);
  translate(-width/2, -height/2);

  background("#E7ECF230");

  noStroke();
  fill(0);

  for (let i = 0; i < shapes.length; i++) {
    shapes[i].move();
    shapes[i].display();
  }

  pop();
}

class Shape {
  constructor(i) {
    this.i = i * 0.01;
    this.A = 0;
    this.B = 0;
    this.S = i % sMax;
  }

  move() {
    this.S += 1;
    if (this.S > sMax) {
      this.S = 0;
    }
  }

  display() {
    this.A = (cos(this.i * 3) - cos(this.i * 6) + 9) * 0.45;
    this.B = this.i / 2 + (sin(this.i * 3) - sin(this.i * 6)) / 3;

    fill(255 * sin(this.B * 10 + frameCount * 0.1), 100, 150);

    circle(
      this.S * this.A * cos(this.B) + width / 2,
      this.S * this.A * sin(this.B) + height / 2,
      this.S * 0.2 * sin(this.i * 11)
    );
  }
}
